import {areas, lessons} from './data.js';
import {questionBank} from './question-bank.js';

const key='orbit-lab-progress-v1';
const saved=(()=>{try{return JSON.parse(localStorage.getItem(key))||{}}catch{return {}}})();
const state={completed:saved.completed||{},scores:saved.scores||{},visits:saved.visits||{},view:'home',lesson:null,qset:null,confirmReset:false,filter:'all',labValue:0,answer:null,questionIndex:0,exam:null};
let examTimer=null;
const app=document.querySelector('#app');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const persist=()=>localStorage.setItem(key,JSON.stringify({completed:state.completed,scores:state.scores,visits:state.visits}));
const area=id=>areas.find(a=>a.id===id);
const count=()=>Object.keys(state.completed).length;
const pct=()=>Math.round(count()/lessons.length*100);
const icon=(name)=>({home:'⌂',map:'▦',exam:'⌁',progress:'◔'}[name]||'◌');

function shell(content){
 app.innerHTML=`<div class="app-shell"><aside class="sidebar"><button class="brand" data-view="home"><span class="brand-mark">✦</span><span>ORBIT<span class="brand-light">LAB</span><small>SCIENCE, EXPLORED.</small></span></button><div class="nav-title">YOUR SPACE</div><nav class="main-nav">${[['home','Dashboard'],['map','Explore topics'],['exam','Practice exam'],['progress','My progress']].map(([id,n])=>`<button class="nav-link ${state.view===id?'active':''}" data-view="${id}"><span>${icon(id)}</span>${n}${id==='map'?`<em>${lessons.length}</em>`:''}</button>`).join('')}</nav><div class="nav-title area-title">DISCOVER</div><nav class="area-nav">${areas.map(a=>`<button class="area-link ${state.view==='map'&&state.filter===a.id?'active':''}" data-area="${a.id}"><i style="--c:${a.color}">${a.icon}</i>${a.name}</button>`).join('')}</nav><div class="side-bottom"><div class="mini-orbit"><span class="planet"></span><span class="mini-stars">✦ · ✧</span></div><strong>Curiosity is a superpower.</strong><p>Keep exploring. Every question makes your science brain stronger.</p></div></aside><div class="main-column"><header class="topbar"><button class="mobile-brand" data-view="home">✦ ORBIT LAB</button><span class="top-label">YEAR 7 <b>·</b> SCIENCE EXPLORER</span><div class="top-right"><span class="top-progress">✦ <b>${count()}</b> / ${lessons.length} missions</span><span class="avatar">S</span></div></header><main>${content}</main><footer>Independent Year 7 science study aid · Inspired by ICAS Science knowledge and skill areas · <a href="https://www.icasassessments.com/icas-year-7-test/" target="_blank" rel="noreferrer">Official ICAS scope ↗</a></footer></div></div>`;
 document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{state.view=el.dataset.view;state.lesson=null;state.confirmReset=false;render();scrollTo(0,0)});
 document.querySelectorAll('[data-area]').forEach(el=>el.onclick=()=>{state.view='map';state.filter=el.dataset.area;state.lesson=null;render();scrollTo(0,0)});
}
function progressRing(value,size=90){return `<div class="progress-ring" style="--p:${value};--size:${size}px"><div><strong>${value}%</strong><small>complete</small></div></div>`}
function home(){let next=lessons.find(l=>!state.completed[l.id])||lessons[0];return `<div class="page home-page"><div class="eyebrow"><span class="pulse-dot"></span> YOUR SCIENCE ADVENTURE STARTS HERE</div><section class="exam-home-banner"><div><span>⌁</span><p><b>Paper E Practice Exam</b>40 questions · 60 minutes · worked review</p></div><button class="primary-btn" data-view="exam">Start an exam →</button></section><section class="hero"><div class="hero-copy"><div class="hero-chip">✦  THE UNIVERSE IS YOUR LAB</div><h1>Think curious.<br><span>Discover everything.</span></h1><p>Journey through the ideas behind Year 7 science. Explore lively models, test your thinking, and collect every mission.</p><div class="hero-actions"><button class="primary-btn" data-open="${next.id}"> ${count()?'Continue exploring':'Start exploring'} <span>↗</span></button><button class="ghost-btn" data-view="map">See all topics <span>→</span></button></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><div class="sun-glow"></div><div class="hero-planet"></div><div class="moon moon-a"></div><div class="moon moon-b"></div><span class="spark s1">✦</span><span class="spark s2">✧</span><span class="spark s3">✦</span></div></section><section class="stats-row"><div class="stat-card"><div class="stat-icon lavender">✦</div><div><strong>${count()} <small>/ ${lessons.length}</small></strong><span>Missions complete</span></div></div><div class="stat-card"><div class="stat-icon mint">◈</div><div><strong>${Object.values(state.scores).filter(Boolean).length}</strong><span>Knowledge checks passed</span></div></div><div class="stat-card stat-progress">${progressRing(pct(),66)}<div><strong>Keep going!</strong><span>Your journey is underway</span></div></div></section><div class="section-heading"><div><span class="kicker">CHOOSE YOUR PATH</span><h2>Explore the science universe</h2><p>Four worlds of ideas. Endless questions to explore.</p></div><button class="text-link" data-view="map">View all topics →</button></div><div class="area-grid">${areas.map((a,i)=>`<button class="area-card area-${a.id}" data-area="${a.id}"><span class="area-number">0${i+1} / 04</span><span class="area-symbol">${a.icon}</span><strong>${a.name}</strong><span>${a.description}</span><span class="area-count">${lessons.filter(l=>l.area===a.id).length} missions <b>↗</b></span></button>`).join('')}</div><section class="next-section"><div><span class="kicker">PICK UP WHERE YOU LEFT OFF</span><h2>Your next mission</h2></div>${lessonCard(next,true)}</section></div>`}
function lessonCard(l,featured=false){let a=area(l.area),done=!!state.completed[l.id];return `<button class="lesson-card ${featured?'featured':''}" data-open="${l.id}"><div class="lesson-icon" style="--c:${a.color}">${l.icon}</div><div class="lesson-info"><span class="lesson-overline">${a.name.toUpperCase()} · ${l.minutes} MIN</span><strong>${l.title}</strong><span>${l.subtitle}</span></div><span class="lesson-status ${done?'done':''}">${done?'✓ Completed':'Explore →'}</span></button>`}
function map(){let filtered=state.filter==='all'?lessons:lessons.filter(l=>l.area===state.filter);return `<div class="page"><div class="page-header"><span class="kicker">MISSION CONTROL · PAPER E</span><h1>Explore the topics<span class="accent-dot">.</span></h1><p>${lessons.length} missions combine knowledge with the five scientific skills used in ICAS Science.</p></div><div class="skill-strip">${['Observing & measuring','Interpreting','Predicting & concluding','Investigating','Reasoning & problem solving'].map((s,i)=>`<span><b>0${i+1}</b>${s}</span>`).join('')}</div><div class="filter-row"><button class="filter ${state.filter==='all'?'selected':''}" data-filter="all">All topics <span>${lessons.length}</span></button>${areas.map(a=>`<button class="filter ${state.filter===a.id?'selected':''}" data-filter="${a.id}">${a.icon} ${a.name}</button>`).join('')}</div><div class="lesson-grid">${filtered.map(l=>lessonCard(l)).join('')}</div></div>`}
function progress(){let byArea=areas.map(a=>({a,n:lessons.filter(l=>l.area===a.id&&state.completed[l.id]).length,total:lessons.filter(l=>l.area===a.id).length}));return `<div class="page"><div class="page-header"><span class="kicker">YOUR FIELD NOTES</span><h1>My progress<span class="accent-dot">.</span></h1><p>Every mission completed is a new way of seeing the world.</p></div><div class="progress-hero"><div>${progressRing(pct(),142)}</div><div><span class="kicker">THE BIG PICTURE</span><h2>${count()===0?'The adventure is just beginning.':count()===lessons.length?'You explored the whole universe!':'Look how far you’ve travelled.'}</h2><p>${count()} of ${lessons.length} lessons completed · ${Object.values(state.scores).filter(Boolean).length} knowledge checks passed</p><button class="primary-btn" data-view="map">Explore missions →</button></div></div><div class="section-heading"><div><span class="kicker">YOUR CONSTELLATIONS</span><h2>Progress by world</h2></div></div><div class="progress-areas">${byArea.map(({a,n,total})=>`<div class="progress-area"><div class="progress-area-head"><span style="color:${a.color}">${a.icon}</span><strong>${a.name}</strong><small>${n}/${total}</small></div><div class="bar"><span style="width:${n/total*100}%;background:${a.color}"></span></div></div>`).join('')}</div><div class="section-heading"><div><span class="kicker">YOUR MISSION LOG</span><h2>All missions</h2></div><button class="text-link" id="export-progress">Export progress ↓</button></div><div class="mission-log">${lessons.map(l=>`<button data-open="${l.id}"><span class="log-check ${state.completed[l.id]?'done':''}">${state.completed[l.id]?'✓':'○'}</span><span>${l.title}<small>${area(l.area).name}</small></span><b>${state.scores[l.id]?'Quiz passed':state.completed[l.id]?'Lesson read':'To explore'}</b></button>`).join('')}</div><section class="reset-card"><div><span class="kicker">START AGAIN</span><h2>Clear everything</h2><p>Removes completed missions, quiz results and any exam in progress from this device so you can begin from scratch. This can’t be undone — use “Export progress” first if you want a backup.</p></div>${state.confirmReset?`<div class="reset-confirm" role="alertdialog" aria-label="Confirm clearing all progress"><strong>Clear all progress?</strong><div><button class="danger-btn" id="reset-yes">Yes, clear everything</button><button class="outline-btn" id="reset-no">Cancel</button></div></div>`:`<button class="outline-btn danger-outline" id="reset-start">Clear everything &amp; start again</button>`}</section></div>`}
const questionsFor=l=>[l.quiz,...(questionBank[l.id]||[])];
function questionMarkup(l){let questions=lessonQuestions(l),q=questions[state.questionIndex]||questions[0],prediction=q.prediction?`<span class="prediction ${q.prediction.toLowerCase()}">${q.prediction} LIKELIHOOD PATTERN · ${q.focus}</span>`:'';return `<span class="kicker">PAPER E QUESTION SET</span><div class="question-progress"><span style="width:${(state.questionIndex+1)/questions.length*100}%"></span></div><div class="question-count">QUESTION ${state.questionIndex+1} OF ${questions.length}</div><h2>Apply the evidence</h2>${prediction}${q.stimulus?`<div class="stimulus"><strong>SCIENTIFIC STIMULUS</strong><p>${q.stimulus}</p></div>`:''}<p>${q.q}</p><div class="options">${q.options.map((o,i)=>`<button class="option" data-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${o}</button>`).join('')}</div><div id="quiz-feedback"></div>`}
function lesson(l){let a=area(l.area),idx=lessons.indexOf(l),next=lessons[idx+1],depth=l.deepDive?`<section class="depth-card"><span class="kicker">ICAS REASONING LENS</span><h2>Go beyond recall</h2><p>${l.deepDive}</p><div class="investigation-box"><strong>Investigation blueprint</strong><p>${l.investigation}</p></div></section>`:`<section class="depth-card compact"><span class="kicker">ICAS REASONING LENS</span><h2>How to think through it</h2><p>Read every axis, unit, label and key before using the stimulus. Separate what you directly observe from what you infer. Eliminate answers that contradict the evidence, then choose the conclusion with the strongest support.</p></section>`;return `<div class="page lesson-page"><button class="back-link" data-view="map">← All topics</button><div class="lesson-hero" style="--lesson-color:${a.color}"><div><span class="lesson-tag">${a.icon} ${a.name.toUpperCase()} <i>·</i> MISSION ${String(idx+1).padStart(2,'0')}</span><h1>${l.title}</h1><p>${l.subtitle}</p><div class="lesson-meta"><span>◷ ${l.minutes} min read</span><span>✦ ${l.skill}</span></div></div><div class="lesson-hero-icon">${l.icon}</div></div><div class="lesson-layout"><article class="lesson-body"><section class="content-card"><span class="kicker">THE BIG IDEA</span><h2>Let’s make sense of it</h2><p class="lead">${l.intro}</p><div class="key-points">${l.points.map((p,i)=>`<div class="key-point"><span>0${i+1}</span><div><strong>${p[0]}</strong><p>${p[1]}</p></div></div>`).join('')}</div></section><section class="example-card"><div class="example-symbol">💡</div><div><span class="kicker">WORKED EVIDENCE</span><h3>Picture this</h3><p>${l.example}</p></div></section>${depth}<section class="lab-card"><div class="lab-heading"><div><span class="kicker">INTERACTIVE LAB</span><h2>${l.lab.label}</h2><p>${l.lab.prompt}</p></div><span class="lab-badge">✦ TRY IT</span></div><div id="lab"></div></section><section class="quiz-card" id="question-set">${questionMarkup(l)}</section><div class="lesson-bottom"><button class="outline-btn" id="mark-done">${state.completed[l.id]?'✓ Mission completed':'✓ Mark lesson complete'}</button>${next?`<button class="primary-btn" data-open="${next.id}">Next mission →</button>`:''}</div></article><aside class="lesson-aside"><div class="aside-card"><span class="kicker">MISSION BRIEF</span><h3>What you’ll learn</h3><div class="brief-item"><span>◈</span> Explain key ideas</div><div class="brief-item"><span>⚙</span> Explore a model</div><div class="brief-item"><span>✦</span> Solve ${questionsFor(l).length} linked questions</div><div class="aside-divider"></div><p>Skill focus</p><strong>${l.skill}</strong></div><div class="aside-note">“The important thing is not to stop questioning.” <span>— Albert Einstein</span></div></aside></div></div>`}

function shuffle(items){for(let i=items.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}return items}
function layoutAnswers(list){const bags={},take=k=>{if(!bags[k]?.length)bags[k]=shuffle(Array.from({length:k},(_,i)=>i));return bags[k].pop()};return list.map(q=>{const target=take(q.options.length),options=shuffle(q.options.filter((_,i)=>i!==q.answer));options.splice(target,0,q.options[q.answer]);return {...q,options,answer:target}})}
function lessonQuestions(l){if(state.qset?.id!==l.id)state.qset={id:l.id,questions:layoutAnswers(questionsFor(l))};return state.qset.questions}
const examSets={balanced:{title:'Set A · Balanced Paper',description:'Even coverage from every mission. Best for a realistic first attempt.'},data:{title:'Set B · Data Detective',description:'Tables, measurements, stimulus interpretation and experimental evidence.'},challenge:{title:'Set C · Challenge Forecast',description:'Forty harder questions based on recurring public-paper patterns.'},skills:{title:'Set D · Skill Sweep',description:'Eight questions from each ICAS skill area: observing, interpreting, predicting, investigating and reasoning.'}};
const skillAreas=['Observing & measuring','Interpreting','Predicting & concluding','Investigating','Reasoning & problem solving'];
function createExam(mode='balanced'){let raw=[];if(mode==='balanced'){for(const l of lessons)raw.push(...shuffle([...questionsFor(l)]).slice(0,2).map(q=>({q,l})))}else if(mode==='data'){for(const a of areas){let pool=lessons.filter(l=>l.area===a.id).flatMap(l=>questionsFor(l).filter(q=>q.stimulus).map(q=>({q,l})));raw.push(...shuffle(pool).slice(0,10))}}else if(mode==='skills'){for(const s of skillAreas){let pool=lessons.filter(l=>l.skill===s).flatMap(l=>questionsFor(l).map(q=>({q,l})));raw.push(...shuffle(pool).slice(0,8))}}else{raw=lessons.flatMap(l=>questionsFor(l).filter(q=>q.prediction).map(q=>({q,l})))}raw=shuffle(raw).slice(0,40);let laid=layoutAnswers(raw.map(({q})=>q)),qs=raw.map(({l},i)=>({...laid[i],lessonId:l.id,topic:l.title,area:l.area,skill:l.skill}));return {mode,title:examSets[mode].title,questions:qs,answers:Array(40).fill(null),index:0,startedAt:Date.now(),duration:60*60,finished:false,submittedAt:null}}
function exam(){let e=state.exam;if(!e)return `<div class="page exam-page"><div class="page-header"><span class="kicker">PAPER E SIMULATOR</span><h1>Practice exams<span class="accent-dot">.</span></h1><p>Choose a full 40-question paper. Every attempt shuffles questions and answer choices.</p></div><section class="exam-intro"><div class="exam-orbit">4<span>exam sets</span></div><div><span class="kicker">EXAM CONDITIONS</span><h2>60 minutes. Four science worlds.</h2><p>Each set targets a different preparation goal while preserving balanced knowledge-area coverage.</p><div class="exam-facts"><span><b>40</b> multiple choice</span><span><b>60</b> minutes</span><span><b>4</b> knowledge areas</span><span><b>1</b> mark each</span></div></div></section><div class="exam-set-grid">${Object.entries(examSets).map(([id,set],i)=>`<article><span>0${i+1}</span><h2>${set.title}</h2><p>${set.description}</p><button class="primary-btn" data-start-exam="${id}">Start this set →</button></article>`).join('')}</div><section class="exam-advice"><strong>Before you begin</strong><p>Have paper, a pencil, ruler and calculator ready. Read stimulus labels and units before looking at the options. You can move between questions and submit early.</p></section></div>`;if(e.finished)return examResults(e);if(e.reviewing)return examReview(e);let q=e.questions[e.index],answered=e.answers.filter(x=>x!==null).length;return `<div class="page exam-page"><div class="exam-top"><div><span class="kicker">${e.title}</span><strong>Question ${e.index+1} of 40</strong></div><div class="exam-time" id="exam-time">60:00</div><button class="outline-btn" id="submit-exam">Review &amp; submit</button></div><div class="exam-layout"><section class="exam-question"><div class="exam-meta"><span style="--c:${area(q.area).color}">${area(q.area).icon} ${area(q.area).name}</span><b>${q.skill}</b></div>${q.stimulus?`<div class="stimulus"><strong>SCIENTIFIC STIMULUS</strong><p>${q.stimulus}</p></div>`:''}<h2>${q.q}</h2><div class="options exam-options">${q.options.map((o,i)=>`<button class="option ${e.answers[e.index]===i?'selected':''}" data-exam-answer="${i}"><span>${String.fromCharCode(65+i)}</span>${o}</button>`).join('')}</div><div class="exam-move"><button class="ghost-btn" id="exam-prev" ${e.index===0?'disabled':''}>← Previous</button><span>${answered}/40 answered</span><button class="primary-btn" id="exam-next">${e.index===39?'Review answers':'Next →'}</button></div></section><aside class="exam-nav"><span class="kicker">QUESTION MAP</span><div class="exam-dots">${e.questions.map((_,i)=>`<button data-exam-go="${i}" class="${i===e.index?'current':''} ${e.answers[i]!==null?'answered':''}">${i+1}</button>`).join('')}</div><div class="exam-key"><span>● Answered</span><span>○ Unanswered</span></div></aside></div></div>`}
function examReview(e){let answered=e.answers.filter(x=>x!==null).length,blank=e.questions.length-answered;return `<div class="page exam-page"><div class="exam-top"><div><span class="kicker">${e.title}</span><strong>Review before submitting</strong></div><div class="exam-time" id="exam-time">60:00</div></div><section class="exam-summary"><span class="kicker">SUBMISSION PREVIEW</span><h2>${blank?`${blank} question${blank>1?'s are':' is'} still unanswered`:`All ${answered} questions answered`}</h2><p>${blank?'Unanswered questions score 0. Select a number to go back to that question, or submit now.':'You can still change any answer. Select a number to revisit a question, or submit when you are ready.'}</p><div class="summary-stats"><span><b>${answered}</b> answered</span><span class="${blank?'warn':''}"><b>${blank}</b> unanswered</span></div><div class="exam-dots summary-dots">${e.questions.map((_,i)=>`<button data-exam-go="${i}" class="${e.answers[i]!==null?'answered':''}" aria-label="Question ${i+1}, ${e.answers[i]!==null?'answered':'unanswered'}">${i+1}</button>`).join('')}</div><div class="summary-actions"><button class="ghost-btn" id="review-back">← Keep working</button>${blank?'<button class="outline-btn" id="review-first">Go to first unanswered</button>':''}<button class="primary-btn" id="review-submit">Submit exam</button></div></section></div>`}
function examResults(e){let correct=e.questions.reduce((n,q,i)=>n+(e.answers[i]===q.answer),0),percent=Math.round(correct/40*100),elapsed=Math.min(e.duration,Math.round((e.submittedAt-e.startedAt)/1000)),byArea=areas.map(a=>{let ids=e.questions.map((q,i)=>q.area===a.id?i:-1).filter(i=>i>=0),score=ids.filter(i=>e.answers[i]===e.questions[i].answer).length;return {a,score,total:ids.length}}),wrong=e.questions.map((q,i)=>({q,i})).filter(({q,i})=>e.answers[i]!==q.answer);return `<div class="page exam-page"><div class="results-hero"><div class="result-score" style="--score:${percent}"><strong>${percent}%</strong><span>${correct} / 40</span></div><div><span class="kicker">EXAM COMPLETE</span><h1>${percent>=85?'Excellent scientific reasoning.':percent>=65?'A strong foundation.':'Your review path is ready.'}</h1><p>Completed in ${Math.floor(elapsed/60)} min ${elapsed%60} sec. Review the explanations below, then generate a fresh paper.</p><button class="primary-btn" id="new-exam">Create another exam ↻</button></div></div><div class="result-areas">${byArea.map(({a,score,total})=>`<div><span style="color:${a.color}">${a.icon}</span><strong>${a.name}</strong><b>${score}/${total}</b><div class="bar"><i style="width:${score/total*100}%;background:${a.color}"></i></div></div>`).join('')}</div><div class="section-heading"><div><span class="kicker">WORKED REVIEW</span><h2>${wrong.length?`${wrong.length} questions to revisit`:'Every answer was correct!'}</h2></div></div><div class="exam-review">${wrong.map(({q,i})=>`<article><span>QUESTION ${i+1} · ${q.topic}</span>${q.stimulus?`<p class="review-stimulus"><b>SCIENTIFIC STIMULUS</b>${q.stimulus}</p>`:''}<h3>${q.q}</h3><p>Your answer: <b>${e.answers[i]===null?'Not answered':q.options[e.answers[i]]}</b></p><p>Correct answer: <strong>${q.options[q.answer]}</strong></p><div>${q.why}</div></article>`).join('')||'<div class="perfect-result">✦ Perfect score — generate another paper for a new mix.</div>'}</div></div>`}
function render(){if(examTimer){clearInterval(examTimer);examTimer=null}shell(state.view==='home'?home():state.view==='map'?map():state.view==='exam'?exam():state.view==='progress'?progress():lesson(state.lesson));bind();}
function bindAnswers(l){document.querySelectorAll('#question-set [data-answer]').forEach(el=>el.onclick=()=>answerQuestion(l,+el.dataset.answer))}
function bind(){document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>openLesson(el.dataset.open));document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{state.filter=el.dataset.filter;render()});document.querySelector('#reset-start')?.addEventListener('click',()=>{state.confirmReset=true;render();document.querySelector('#reset-no')?.focus()});document.querySelector('#reset-no')?.addEventListener('click',()=>{state.confirmReset=false;render()});document.querySelector('#reset-yes')?.addEventListener('click',resetAll);document.querySelector('#export-progress')?.addEventListener('click',()=>{let blob=new Blob([JSON.stringify({app:'Orbit Lab',exported:new Date().toISOString(),completed:state.completed,scores:state.scores},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='orbit-lab-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});if(state.view==='lesson'){setupLab(state.lesson);bindAnswers(state.lesson);document.querySelector('#mark-done').onclick=()=>{state.completed[state.lesson.id]=true;persist();render()}}if(state.view==='exam')bindExam()}
function bindExam(){let e=state.exam,starters=document.querySelectorAll('[data-start-exam]');if(starters.length){starters.forEach(el=>el.onclick=()=>{state.exam=createExam(el.dataset.startExam);render();scrollTo(0,0)});return}let fresh=document.querySelector('#new-exam');if(fresh){fresh.onclick=()=>{state.exam=null;render();scrollTo(0,0)};return}if(!e||e.finished)return;document.querySelectorAll('[data-exam-go]').forEach(el=>el.onclick=()=>{let fromReview=e.reviewing;e.index=+el.dataset.examGo;e.reviewing=false;render();if(fromReview)scrollTo(0,0)});if(e.reviewing){document.querySelector('#review-back').onclick=()=>{e.reviewing=false;render();scrollTo(0,0)};document.querySelector('#review-first')?.addEventListener('click',()=>{e.index=Math.max(0,e.answers.indexOf(null));e.reviewing=false;render();scrollTo(0,0)});document.querySelector('#review-submit').onclick=()=>finishExam()}else{document.querySelectorAll('[data-exam-answer]').forEach(el=>el.onclick=()=>{e.answers[e.index]=+el.dataset.examAnswer;render()});document.querySelector('#exam-prev').onclick=()=>{if(e.index>0){e.index--;render()}};document.querySelector('#exam-next').onclick=()=>{if(e.index<e.questions.length-1){e.index++;render()}else{e.reviewing=true;render();scrollTo(0,0)}};document.querySelector('#submit-exam').onclick=()=>{e.reviewing=true;render();scrollTo(0,0)}}let tick=()=>{let remaining=Math.max(0,e.duration-Math.floor((Date.now()-e.startedAt)/1000)),node=document.querySelector('#exam-time');if(node)node.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if(remaining===0)finishExam()};tick();examTimer=setInterval(tick,1000)}
function resetAll(){Object.assign(state,{completed:{},scores:{},visits:{},exam:null,qset:null,lesson:null,questionIndex:0,answer:null,labValue:0,filter:'all',confirmReset:false,view:'home'});try{localStorage.removeItem(key)}catch{}render();scrollTo(0,0)}
function finishExam(){if(!state.exam||state.exam.finished)return;state.exam.finished=true;state.exam.submittedAt=Date.now();render();scrollTo(0,0)}
function openLesson(id){state.lesson=lessons.find(l=>l.id===id);state.view='lesson';state.labValue=0;state.answer=null;state.questionIndex=0;state.qset=null;state.visits[id]=(state.visits[id]||0)+1;persist();render();scrollTo(0,0)}
function answerQuestion(l,i){let questions=lessonQuestions(l),q=questions[state.questionIndex],correct=i===q.answer,last=state.questionIndex===questions.length-1;document.querySelectorAll('#question-set .option').forEach(el=>{let n=+el.dataset.answer;el.classList.toggle('correct',n===q.answer);el.classList.toggle('incorrect',n===i&&!correct);el.disabled=true});if(correct&&last){state.scores[l.id]=true;state.completed[l.id]=true;persist()}let action=!last&&correct?'<button class="feedback-next" id="next-question">Next question →</button>':!correct?'<button class="feedback-next" id="retry-question">Try another answer ↻</button>':'';document.querySelector('#quiz-feedback').innerHTML=`<div class="feedback ${correct?'good':'try'}"><strong>${correct?(last?'Question set complete!':'Correct — follow the evidence.'): 'Good attempt — inspect the evidence again.'}</strong><p>${q.why}</p>${action}</div>`;document.querySelector('#next-question')?.addEventListener('click',()=>{state.questionIndex++;refreshQuestion(l)});document.querySelector('#retry-question')?.addEventListener('click',()=>refreshQuestion(l));document.querySelector('#mark-done').textContent=state.completed[l.id]?'✓ Mission completed':'✓ Mark lesson complete';}
function refreshQuestion(l){document.querySelector('#question-set').innerHTML=questionMarkup(l);bindAnswers(l);document.querySelector('#question-set').scrollIntoView({behavior:'smooth',block:'center'})}

function setupLab(l){const box=document.querySelector('#lab');let t=l.lab.type;const range=(name,min,max,val,unit='')=>`<label class="range-label">${name} <b id="range-value">${val}${unit}</b></label><input id="lab-range" type="range" min="${min}" max="${max}" value="${val}" aria-label="${name}">`;
 if(t==='particles'){box.innerHTML=`<div class="sim-stage particle-stage"><div class="particle-container" id="particles"></div></div>${range('Temperature',0,100,25,'°C')}<p class="lab-readout" id="lab-readout"></p>`;let draw=v=>{let gas=v>72,liquid=v>34;document.querySelector('#particles').innerHTML=Array.from({length:20},(_,i)=>`<i class="particle ${gas?'gas':liquid?'liquid':'solid'}" style="left:${9+(i%5)*19}%;top:${12+Math.floor(i/5)*23}%;--speed:${(2.8-v/60).toFixed(2)}s;animation-delay:${(i*-.13).toFixed(2)}s"></i>`).join('');document.querySelector('#range-value').textContent=v+'°C';document.querySelector('#lab-readout').textContent=gas?'Gas: particles spread out and move rapidly.':liquid?'Liquid: particles stay close but slide past one another.':'Solid: particles vibrate near fixed positions.'};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(25)}
 else if(t==='forces'){box.innerHTML=`<div class="sim-stage force-stage"><div class="force-arrow left" id="left-arrow">←</div><div class="force-block">▣</div><div class="force-arrow right" id="right-arrow">→</div></div><div class="dual-range"><div>${range('Force left',0,20,8,' N').replaceAll('lab-range','left-range').replaceAll('range-value','left-value')}</div><div>${range('Force right',0,20,12,' N').replaceAll('lab-range','right-range').replaceAll('range-value','right-value')}</div></div><p class="lab-readout" id="lab-readout"></p>`;let draw=()=>{let left=+document.querySelector('#left-range').value,right=+document.querySelector('#right-range').value,n=right-left;document.querySelector('#left-value').textContent=left+' N';document.querySelector('#right-value').textContent=right+' N';document.querySelector('#left-arrow').style.transform=`scaleX(${.6+left/20})`;document.querySelector('#right-arrow').style.transform=`scaleX(${.6+right/20})`;document.querySelector('#lab-readout').textContent=n===0?'Balanced: net force is 0 N.':`Net force: ${Math.abs(n)} N ${n>0?'right':'left'}. The block accelerates ${n>0?'right':'left'}.`};document.querySelectorAll('input').forEach(e=>e.oninput=draw);draw()}
 else if(t==='circuit'){box.innerHTML=`<div class="sim-stage circuit-stage"><div class="circuit-wire"><div class="battery" id="battery">+ −</div><div class="bulb" id="bulb">✺</div><div class="switch" id="switch-icon">╱</div></div></div><div class="lab-controls"><button class="lab-control" id="switch-btn">Close switch</button><button class="lab-control" id="battery-btn">Add battery</button></div><p class="lab-readout" id="lab-readout"></p>`;let closed=false,bats=1;function draw(){document.querySelector('#bulb').classList.toggle('lit',closed);document.querySelector('#switch-icon').textContent=closed?'━':'╱';document.querySelector('#battery').textContent=bats===1?'+ −':'+ −  + −';document.querySelector('#switch-btn').textContent=closed?'Open switch':'Close switch';document.querySelector('#battery-btn').textContent=bats===1?'Add battery':'Remove battery';document.querySelector('#lab-readout').textContent=closed?`Closed loop: current flows and the lamp glows${bats===2?' more brightly in this model':''}.`:'Open loop: the break stops current.'}document.querySelector('#switch-btn').onclick=()=>{closed=!closed;draw()};document.querySelector('#battery-btn').onclick=()=>{bats=bats===1?2:1;draw()};draw()}
 else if(t==='tilt'){box.innerHTML=`<div class="sim-stage tilt-stage"><div class="tilt-sun">☀</div><div class="orbit-line"></div><div class="tilt-earth" id="tilt-earth"><span>🌏</span><i></i></div></div>${range('Month',1,12,1)}<p class="lab-readout" id="lab-readout"></p>`;let draw=v=>{let rad=(v-1)/12*Math.PI*2,x=50+37*Math.cos(rad),y=50+35*Math.sin(rad);document.querySelector('#tilt-earth').style.left=x+'%';document.querySelector('#tilt-earth').style.top=y+'%';document.querySelector('#range-value').textContent=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][v-1];document.querySelector('#lab-readout').textContent=v<=2||v>=11?'Southern Hemisphere summer: longer days and more direct sunlight.':v>=5&&v<=8?'Southern Hemisphere winter: shorter days and less direct sunlight.':'Around an equinox: day and night are closer to equal length.'};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(1)}
 else if(t==='scale'){let planets=[['Mercury',.39],['Venus',.72],['Earth',1],['Mars',1.52],['Jupiter',5.2],['Saturn',9.58],['Uranus',19.2],['Neptune',30.1]];box.innerHTML=`<div class="sim-stage scale-stage"><div class="scale-sun">☀</div><div class="scale-track"><span id="scale-planet">●</span></div><div class="scale-name" id="scale-name"></div></div>${range('Planet',0,7,2)}<p class="lab-readout" id="lab-readout"></p>`;let draw=v=>{let [name,au]=planets[v];document.querySelector('#range-value').textContent=name;document.querySelector('#scale-name').textContent=name;document.querySelector('#scale-planet').style.left=(Math.log(au+1)/Math.log(31.1)*95)+'%';document.querySelector('#lab-readout').textContent=`${name} is about ${au} AU from the Sun. This screen uses a compressed scale so outer planets fit.`};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(2)}
 else if(t==='pulse'||t==='web'){box.innerHTML=`<div class="sim-stage ${t}-stage">${t==='pulse'?'<div class="heart-graphic" id="heart">♥</div><div class="pulse-line">⌁⌁⌁⌁⌁</div>':'<div class="web-nodes"><span>☘<small>plants</small></span><b>→</b><span>🐛<small>insects</small></span><b>→</b><span>🐦<small>birds</small></span></div>'}</div>${range(t==='pulse'?'Exercise effort':'Insect population',0,100,50,'%')}<p class="lab-readout" id="lab-readout"></p>`;let draw=v=>{document.querySelector('#range-value').textContent=v+'%';if(t==='pulse'){document.querySelector('#heart').style.animationDuration=(1.3-v*.008)+'s';document.querySelector('#lab-readout').textContent=`Model: heart rate ${Math.round(70+v*.9)} bpm, breathing rate ${Math.round(14+v*.25)} breaths/min. Real responses vary.`}else document.querySelector('#lab-readout').textContent=v<30?'Few insects: birds may have less food; more plants may survive.':v>70?'Many insects: birds may have more food; more plants may be eaten.':'Balanced insect population: several feeding relationships are supported.'};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(50)}
 else if(t==='watercycle'){const stages=['Evaporation','Condensation','Precipitation','Collection'],notes=['The Sun warms the ocean surface; rising vapour is drawn upward as invisible gas.','Vapour cools high in the atmosphere and condenses into tiny droplets, forming clouds.','Droplets combine until they are heavy enough to fall as rain, snow or hail.','Water gathers again in oceans, rivers and groundwater, ready to evaporate once more.'];box.innerHTML=`<div class="sim-stage watercycle-stage" id="wc-stage"><div class="wc-sun">☀</div><div class="wc-cloud" id="wc-cloud">☁</div><div class="wc-drops">${Array.from({length:6},(_,i)=>`<i class="rise-drop" style="left:${14+i*13}%;animation-delay:${(i*-.5).toFixed(1)}s"></i>`).join('')}</div><div class="wc-rain">${Array.from({length:6},(_,i)=>`<i class="rain-drop" style="left:${20+i*11}%;animation-delay:${(i*-.35).toFixed(1)}s"></i>`).join('')}</div><div class="wc-ocean"></div></div>${range('Stage',0,3,0)}<p class="lab-readout" id="lab-readout"></p>`;let draw=v=>{document.querySelector('#range-value').textContent=stages[v];document.querySelector('#wc-stage').dataset.stage=v;document.querySelector('#lab-readout').textContent=`${stages[v]}: ${notes[v]}`};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(0)}
 else if(t==='reactions'){box.innerHTML=`<div class="sim-stage reaction-stage" id="rx-stage"><div class="rx-side rx-reactants"><span class="atom mg">Mg</span><span class="atom mg">Mg</span><span class="atom o">O₂</span></div><div class="rx-arrow">→</div><div class="rx-side rx-products"><span class="atom mgo">MgO</span><span class="atom mgo">MgO</span></div></div><div class="lab-controls"><button class="lab-control" id="react-btn">React →</button><button class="lab-control" id="rx-reset">Reset</button></div><p class="lab-readout" id="lab-readout"></p>`;let reacted=false;const draw=()=>{document.querySelector('#rx-stage').classList.toggle('reacted',reacted);document.querySelector('#react-btn').disabled=reacted;document.querySelector('#lab-readout').textContent=reacted?'10 g magnesium + 6.6 g oxygen → 16.6 g magnesium oxide. Same atoms, rearranged: mass is conserved.':'10 g magnesium and 6.6 g oxygen, not yet reacted. Press React to heat the mixture.'};document.querySelector('#react-btn').onclick=()=>{reacted=true;draw()};document.querySelector('#rx-reset').onclick=()=>{reacted=false;draw()};draw()}
 else if(t==='sampling'){const dots=Array.from({length:36},()=>({x:4+Math.random()*90,y:4+Math.random()*90}));box.innerHTML=`<div class="sim-stage sampling-stage" id="field">${dots.map(d=>`<i class="field-dot" style="left:${d.x}%;top:${d.y}%" data-x="${d.x}" data-y="${d.y}"></i>`).join('')}<div class="quadrat" id="quadrat" hidden></div></div><div class="lab-controls"><button class="lab-control" id="sample-btn">Drop a random quadrat →</button><button class="lab-control" id="sample-reset">Reset samples</button></div><p class="lab-readout" id="lab-readout"></p>`;const quadSize=22,samples=[];const draw=()=>{if(!samples.length){document.querySelector('#lab-readout').textContent='No samples yet. Drop a quadrat to count plants inside it.';return}let mean=samples.reduce((a,b)=>a+b,0)/samples.length,estimate=Math.round(mean*(10000/(quadSize*quadSize)));document.querySelector('#lab-readout').textContent=`Samples: ${samples.join(', ')} · mean ${mean.toFixed(1)} per quadrat · estimated field population ≈ ${estimate}.`};document.querySelector('#sample-btn').onclick=()=>{let qx=Math.random()*(100-quadSize),qy=Math.random()*(100-quadSize),q=document.querySelector('#quadrat');q.hidden=false;q.style.left=qx+'%';q.style.top=qy+'%';q.style.width=quadSize+'%';q.style.height=quadSize+'%';let count=0;document.querySelectorAll('.field-dot').forEach(el=>{let x=+el.dataset.x,y=+el.dataset.y,inside=x>=qx&&x<=qx+quadSize&&y>=qy&&y<=qy+quadSize;el.classList.toggle('in-quadrat',inside);if(inside)count++});samples.push(count);draw()};document.querySelector('#sample-reset').onclick=()=>{samples.length=0;document.querySelector('#quadrat').hidden=true;document.querySelectorAll('.field-dot').forEach(el=>el.classList.remove('in-quadrat'));draw()};draw()}
 else if(t==='vtgraph'){const vAt=t=>t<=3?4*t:t<=7?12:t<=9?Math.max(0,12-6*(t-7)):0,dAt=t=>t<=3?2*t*t:t<=7?18+12*(t-3):t<=9?66+(12*(t-7)-3*(t-7)*(t-7)):78,sx=t=>10+t/9*280,sy=v=>150-v/12*130;box.innerHTML=`<div class="sim-stage vt-stage"><svg viewBox="0 0 300 160" class="vt-svg"><line x1="10" y1="150" x2="290" y2="150" class="vt-axis"/><line x1="10" y1="10" x2="10" y2="150" class="vt-axis"/><polygon id="vt-area" class="vt-area" points="10,150 10,150"/><polyline class="vt-line" points="10,150 103,20 228,20 290,150"/><line id="vt-marker" class="vt-marker" x1="10" y1="10" x2="10" y2="150"/></svg></div>${range('Time',0,9,0,' s')}<p class="lab-readout" id="lab-readout"></p>`;let draw=t=>{let pts=[];for(let x=0;x<=t;x+=.3)pts.push(`${sx(x).toFixed(1)},${sy(vAt(x)).toFixed(1)}`);pts.push(`${sx(t).toFixed(1)},${sy(vAt(t)).toFixed(1)}`);document.querySelector('#vt-area').setAttribute('points',`10,150 ${pts.join(' ')} ${sx(t).toFixed(1)},150`);document.querySelector('#vt-marker').setAttribute('x1',sx(t));document.querySelector('#vt-marker').setAttribute('x2',sx(t));document.querySelector('#range-value').textContent=t+' s';document.querySelector('#lab-readout').textContent=`At t = ${t} s: velocity ≈ ${vAt(t).toFixed(1)} m/s. The shaded area under the graph is the distance travelled: ≈ ${dAt(t).toFixed(1)} m.`};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(0)}
 else if(t==='rocket'){const volumes=[20,40,60],heights=[14,22,19],best=Math.max(...heights);box.innerHTML=`<div class="sim-stage rocket-stage"><div class="rocket-ruler"><i></i><i></i><i></i><i></i></div><div class="rocket" id="rocket-icon">🚀</div><div class="rocket-pad"></div></div>${range('Water volume',0,2,0)}<div class="lab-controls"><button class="lab-control" id="launch-btn">Launch →</button></div><p class="lab-readout" id="lab-readout"></p>`;let draw=v=>{document.querySelector('#range-value').textContent=volumes[v]+'%';document.querySelector('#lab-readout').textContent=`${volumes[v]}% water loaded. Press Launch to test this volume.`};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);document.querySelector('#launch-btn').onclick=()=>{let v=+document.querySelector('#lab-range').value,h=heights[v],icon=document.querySelector('#rocket-icon');icon.style.transition='none';icon.style.setProperty('--h','0px');requestAnimationFrame(()=>requestAnimationFrame(()=>{icon.style.transition='transform 1s cubic-bezier(.2,.8,.3,1)';icon.style.setProperty('--h',(h*7)+'px')}));document.querySelector('#lab-readout').textContent=`${volumes[v]}% water → ${h} m. ${h===best?'The greatest height among the volumes tested.':'Compare with the other tested volumes — height does not simply rise with more water.'}`};draw(0)}
 else if(t==='plates'){const modes={divergent:'New crust forms at the ridge as the plates pull apart; ocean rocks are youngest at the centre and older away from it.',convergent:'One plate is forced down beneath the other (subduction), producing a trench, earthquakes and volcanoes.',transform:'Plates slide sideways past each other, producing earthquakes but little new crust or trench.'};box.innerHTML=`<div class="sim-stage plates-stage" id="plates-stage" data-mode="divergent"><div class="plate plate-left"></div><div class="boundary-glow"></div><div class="plate plate-right"></div></div><div class="lab-controls">${Object.keys(modes).map(m=>`<button class="lab-control" data-mode="${m}">${m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</div><p class="lab-readout" id="lab-readout"></p>`;let draw=m=>{document.querySelector('#plates-stage').dataset.mode=m;document.querySelector('#lab-readout').textContent=`${m[0].toUpperCase()+m.slice(1)} boundary: ${modes[m]}`;document.querySelectorAll('.lab-controls [data-mode]').forEach(el=>el.classList.toggle('active',el.dataset.mode===m))};document.querySelectorAll('.lab-controls [data-mode]').forEach(el=>el.onclick=()=>draw(el.dataset.mode));draw('divergent')}
 else if(t==='scaledraw'){box.innerHTML=`<div class="sim-stage scaledraw-stage"><div class="beam-wrap"><div class="beam" id="beam"></div></div></div><label class="range-label">Plan length <b id="range-value">7.2 cm</b></label><input id="lab-range" type="range" min="1" max="12" step="0.1" value="7.2" aria-label="Plan length"><div class="lab-controls">${[50,100,200].map(r=>`<button class="lab-control" data-ratio="${r}">1:${r}</button>`).join('')}</div><p class="lab-readout" id="lab-readout"></p>`;let ratio=100;let draw=()=>{let plan=+document.querySelector('#lab-range').value,realCm=plan*ratio,realM=realCm/100;document.querySelector('#range-value').textContent=plan.toFixed(1)+' cm';document.querySelector('#beam').style.width=Math.min(220,Math.max(24,plan*16))+'px';document.querySelector('#lab-readout').textContent=`${plan.toFixed(1)} cm at 1:${ratio} → real length = ${plan.toFixed(1)} × ${ratio} = ${realCm.toFixed(0)} cm = ${realM.toFixed(2)} m.`;document.querySelectorAll('[data-ratio]').forEach(el=>el.classList.toggle('active',+el.dataset.ratio===ratio))};document.querySelector('#lab-range').oninput=draw;document.querySelectorAll('[data-ratio]').forEach(el=>el.onclick=()=>{ratio=+el.dataset.ratio;draw()});draw()}
 else if(t==='river'){const nitrate=[0.4,1.8,3.6,5.4,6.8],oxygen=[8.1,6.9,5.4,4.1,3.2],labels=['At the farm','1 km','2 km','3 km','4 km'];box.innerHTML=`<div class="sim-stage river-stage"><div class="farm">🚜</div><div class="river-flow"></div><div class="algae" id="algae"></div><div class="marker" id="river-marker"></div></div>${range('Distance downstream',0,4,0)}<p class="lab-readout" id="lab-readout"></p>`;let draw=v=>{document.querySelector('#range-value').textContent=labels[v];document.querySelector('#river-marker').style.left=(10+v*20)+'%';document.querySelector('#algae').innerHTML=Array.from({length:Math.round(nitrate[v]*2)},(_,i)=>`<i style="left:${8+v*20+(i%4)*3}%;top:${58+Math.floor(i/4)*12}%"></i>`).join('');let low=oxygen[v]<5;document.querySelector('#lab-readout').textContent=`${labels[v]}: nitrate ${nitrate[v]} mg/L, dissolved oxygen ${oxygen[v]} mg/L. ${low?'Oxygen has fallen low enough here to stress fish and other aquatic life.':'Oxygen is still fairly high at this point.'}`};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(0)}
 else if(t==='key'){const nodes={start:{q:'How many legs does it have?',options:[{label:'Six legs',key:'six',next:'wings'},{label:'Eight legs',key:'eight',next:null,result:'Spider'}]},wings:{q:'How many pairs of wings?',options:[{label:'One pair',key:'one',next:null,result:'Fly'},{label:'Two pairs',key:'two',next:'waist'}]},waist:{q:'Is its waist narrow?',options:[{label:'Narrow waist',key:'narrow',next:null,result:'Wasp'},{label:'Not narrow',key:'wide',next:null,result:'Termite'}]}},specimens=[{name:'Spider',icon:'🕷️',legs:'eight'},{name:'Fly',icon:'🪰',legs:'six',wings:'one'},{name:'Wasp',icon:'🐝',legs:'six',wings:'two',waist:'narrow'},{name:'Termite',icon:'🐛',legs:'six',wings:'two',waist:'wide'}];box.innerHTML=`<div class="sim-stage key-stage"><div class="key-specimen" id="key-specimen"></div><div class="key-card"><strong id="key-question"></strong><div class="choice-buttons" id="key-options"></div></div></div><div class="lab-controls"><button class="lab-control" id="key-new">New specimen →</button></div><p class="lab-readout" id="lab-readout"></p>`;let specimen,node;const renderStep=()=>{let n=nodes[node];document.querySelector('#key-question').textContent=n.q;document.querySelector('#key-options').innerHTML=n.options.map(o=>`<button class="lab-control" data-key="${o.key}">${o.label}</button>`).join('');document.querySelectorAll('[data-key]').forEach(el=>el.onclick=()=>choose(n.options.find(o=>o.key===el.dataset.key)))};const choose=opt=>{let trueVal=node==='start'?specimen.legs:node==='wings'?specimen.wings:specimen.waist;if(opt.key!==trueVal){document.querySelector('#lab-readout').textContent='Look at the specimen again — that doesn’t match it. Try the other option.';return}if(opt.result){document.querySelector('#key-question').textContent=`Identified: ${opt.result}`;document.querySelector('#key-options').innerHTML='';document.querySelector('#lab-readout').textContent=`Correct — the key’s branches match this specimen all the way to ${opt.result}. Press “New specimen” to try another.`}else{node=opt.next;renderStep();document.querySelector('#lab-readout').textContent='Good — that matches. Continue to the next step.'}};const newSpecimen=()=>{specimen=specimens[Math.floor(Math.random()*specimens.length)];document.querySelector('#key-specimen').textContent=specimen.icon;node='start';renderStep();document.querySelector('#lab-readout').textContent='A new specimen has appeared. Start at step 1.'};document.querySelector('#key-new').onclick=newSpecimen;newSpecimen()}
 else if(t==='raydiagram'){const cx=150,cy=140,L=95,pt=(a,sign)=>[cx+sign*L*Math.sin(a*Math.PI/180),cy-L*Math.cos(a*Math.PI/180)];box.innerHTML=`<div class="sim-stage ray-stage"><svg viewBox="0 0 300 160" class="ray-svg"><line x1="20" y1="${cy}" x2="280" y2="${cy}" class="ray-mirror"/><line x1="${cx}" y1="${cy}" x2="${cx}" y2="30" class="ray-normal"/><line id="ray-in" class="ray-line"/><line id="ray-out" class="ray-line"/><circle cx="${cx}" cy="${cy}" r="3" class="ray-point"/></svg></div>${range('Angle of incidence',5,80,35,'°')}<p class="lab-readout" id="lab-readout"></p>`;let draw=a=>{let [sx1,sy1]=pt(a,-1),[sx2,sy2]=pt(a,1);document.querySelector('#ray-in').setAttribute('x1',sx1);document.querySelector('#ray-in').setAttribute('y1',sy1);document.querySelector('#ray-in').setAttribute('x2',cx);document.querySelector('#ray-in').setAttribute('y2',cy);document.querySelector('#ray-out').setAttribute('x1',cx);document.querySelector('#ray-out').setAttribute('y1',cy);document.querySelector('#ray-out').setAttribute('x2',sx2);document.querySelector('#ray-out').setAttribute('y2',sy2);document.querySelector('#range-value').textContent=a+'°';document.querySelector('#lab-readout').textContent=`Incidence angle = ${a}° from the normal. Reflection angle = ${a}° (equal). Measured from the mirror surface instead, each ray makes ${90-a}°.`};document.querySelector('#lab-range').oninput=e=>draw(+e.target.value);draw(35)}
 else{const sets={cycle:[['Magma','Liquid rock below the surface.'],['Igneous rock','Cooling makes crystals.'],['Sediment','Weathering and erosion make fragments.'],['Sedimentary rock','Layers compact and cement together.'],['Metamorphic rock','Heat and pressure change existing rock.']],separate:[['Sand + water','Filter: sand grains stay in the paper.'],['Salt + water','Evaporate: salt remains as crystals.'],['Ink colours','Chromatography: dyes travel at different rates.']],classify:[['Ice melts','Physical: the particles are still water.'],['Iron rusts','Chemical: new iron oxide forms.'],['Sugar dissolves','Physical: sugar particles disperse in water.'],['Wood burns','Chemical: new gases and ash form.']],cell:[['Cell wall','A firm outer layer supports plant cells.'],['Membrane','Controls entry and exit.'],['Nucleus','Holds genetic information.'],['Chloroplast','Captures light for photosynthesis.'],['Vacuole','Stores water and helps keep the cell firm.']],transfer:[['Torch','Chemical → electrical → light + heat'],['Bicycle','Chemical energy in food → movement + heat'],['Solar panel','Light → electrical energy'],['Speaker','Electrical → sound + heat']],systems:[['Digestive system','Breaks food into small molecules the body can absorb.'],['Nervous system','Detects stimuli and coordinates fast responses through nerves and the brain.'],['Skeletal-muscular system','Bones support and protect; muscles contract to move joints.'],['Circulatory link','Blood carries digested nutrients and oxygen to the cells that need them.']],sources:[['Solar','Renewable; no fuel needed, but little output at night.'],['Wind','Renewable; no emissions in use, but output depends on wind speed.'],['Coal','Non-renewable; reliable output, but releases greenhouse gases.'],['Hydroelectric','Renewable; reliable with stored water, but dams affect river ecosystems.']]};let items=sets[t],current=0;box.innerHTML=`<div class="sim-stage choice-stage"><div class="choice-visual" id="choice-visual">${t==='cell'?'◉':t==='transfer'?'⚡':t==='cycle'?'◈':t==='separate'?'◐':'✺'}</div><div id="choice-title"></div></div><div class="choice-buttons">${items.map((it,i)=>`<button class="lab-control" data-choice="${i}">${it[0]}</button>`).join('')}</div><p class="lab-readout" id="lab-readout"></p>`;let draw=i=>{current=i;document.querySelector('#choice-title').textContent=items[i][0];document.querySelector('#lab-readout').textContent=items[i][1];document.querySelectorAll('[data-choice]').forEach(el=>el.classList.toggle('active',+el.dataset.choice===i))};document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>draw(+el.dataset.choice));draw(current)}
 enhanceLab3D(box,t);
}

function enhanceLab3D(box,type){
 const stage=box.querySelector('.sim-stage');if(!stage)return;
 stage.classList.add('stage-3d');stage.setAttribute('aria-label','Interactive 3D model. Drag to rotate.');
 const world=document.createElement('div');world.className='scene-world';while(stage.firstChild)world.append(stage.firstChild);stage.append(world);
 const hint=document.createElement('span');hint.className='drag-hint';hint.textContent='↔ DRAG TO ROTATE';stage.append(hint);
 if(type==='forces'){const cube=world.querySelector('.force-block');cube.innerHTML='<i class="cube-face front">F</i><i class="cube-face back">F</i><i class="cube-face right"></i><i class="cube-face left"></i><i class="cube-face top"></i><i class="cube-face bottom"></i>'}
 if(type==='tilt'){world.insertAdjacentHTML('beforeend','<div class="starfield"></div><div class="sun-rays"></div>');world.querySelector('.tilt-earth span').textContent='';world.querySelector('.tilt-earth').insertAdjacentHTML('afterbegin','<b class="earth-globe"><i></i></b>')}
 if(type==='scale'){world.querySelector('#scale-planet').innerHTML='<i></i>';world.insertAdjacentHTML('afterbegin','<div class="starfield"></div>')}
 if(type==='circuit'){world.insertAdjacentHTML('beforeend','<div class="electron e1">•</div><div class="electron e2">•</div><div class="electron e3">•</div>')}
 if(type==='cell'){const visual=world.querySelector('#choice-visual');visual.className='cell-model';visual.innerHTML='<span class="cell-wall"></span><span class="cell-vacuole"></span><span class="cell-nucleus"></span><i class="chloroplast c1"></i><i class="chloroplast c2"></i><i class="chloroplast c3"></i>'}
 let dragging=false,startX=0,startY=0,rx=-8,ry=-12;
 const update=()=>{world.style.setProperty('--rx',rx+'deg');world.style.setProperty('--ry',ry+'deg')};update();
 stage.onpointerdown=e=>{dragging=true;startX=e.clientX;startY=e.clientY;stage.setPointerCapture(e.pointerId);stage.classList.add('dragging')};
 stage.onpointermove=e=>{if(!dragging)return;ry+=(e.clientX-startX)*.35;rx=Math.max(-35,Math.min(35,rx-(e.clientY-startY)*.25));startX=e.clientX;startY=e.clientY;update()};
 stage.onpointerup=stage.onpointercancel=()=>{dragging=false;stage.classList.remove('dragging')};
}
render();
